<?php require_once 'config/config.php'; require_manager();$rid=room_id();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$item=trim($_POST['item']??'');$qty=trim($_POST['quantity']??'');$amount=(float)($_POST['amount']??0);$date=$_POST['date']??date('Y-m-d');$note=trim($_POST['note']??'');if($item===''||$amount<=0)$error='Enter item and a valid amount.';else{db()->prepare("INSERT INTO bazar(room_id,purchased_by,item,quantity,amount,purchase_date,note) VALUES(?,?,?,?,?,?,?)")->execute([$rid,user()['id'],$item,$qty,$amount,$date,$note]);db()->prepare("INSERT INTO expenses(room_id,category,description,amount,expense_date,created_by) VALUES(?,?,?,?,?,?)")->execute([$rid,'Bazar',$item,$amount,$date,user()['id']]);flash('Bazar item added.');redirect('bazar.php');}}
$q=db()->prepare("SELECT b.*,u.name FROM bazar b JOIN users u ON u.id=b.purchased_by WHERE b.room_id=? ORDER BY b.purchase_date DESC,b.id DESC LIMIT 100");$q->execute([$rid]);$rows=$q->fetchAll();$title='Bazar';include 'includes/header.php';?><div class="d-flex justify-content-between mb-4"><div><h2 class="fw-bold">Bazar & shopping</h2><p class="small-muted">Every purchase is automatically added to monthly expenses.</p></div></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="card p-4 mb-4"><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="col-md-3"><input class="form-control" name="item" placeholder="Item e.g. rice" required></div><div class="col-md-2"><input class="form-control" name="quantity" placeholder="Quantity"></div><div class="col-md-2"><input class="form-control" name="amount" type="number" step=".01" placeholder="Amount ৳" required></div><div class="col-md-2"><input class="form-control" name="date" type="date" value="<?=date('Y-m-d')?>"></div><div class="col-md-2"><input class="form-control" name="note" placeholder="Note"></div><div class="col-md-1"><button class="btn btn-dark w-100">Add</button></div></form></div><div class="card p-4"><div class="table-responsive"><table class="table"><thead><tr><th>Date</th><th>Item</th><th>Qty</th><th>Buyer</th><th>Amount</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['purchase_date'])?></td><td><?=e($r['item'])?></td><td><?=e($r['quantity'])?></td><td><?=e($r['name'])?></td><td><?=money((float)$r['amount'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php include 'includes/footer.php';?>